params.text:
{{
    user
    for user
    in CTX.hs_users
    if user.teams
    and any(team.id in CTX.cs_team_ids for team in user.teams)
}}

{{-
[
  {
    "label": contact.properties.discord_username ~ " (" ~ contact.properties.email ~ ")",
    "id": contact.properties.discord_username ~ "," ~ contact.properties.discord_id
  }
  for contact in CTX.filtered_contact_output
  if contact.properties.discord_username and contact.properties.discord_id and contact.properties.discord_id != "Not Found"
]
-}}

schema.text:
**CSM:** {{ CTX.csm.label }}

**Company Name:** {{ CTX.company.label.split("(")|first }}

**Company Domain:** {{ CTX.company.value }}

**Discord Username:** {{ CTX.discord_user.value }}

**Contact Email:** {{ (CTX.discord_user.label.split("(")|last).split(")")|first }}

params.text:
{{ [
  {
    "label": company.properties.name ~ ", " ~ (company.properties.domain | replace(".", "-")) ~ " (" ~ (company.properties.discord_server | default("REWST-COMMUNITY", true))~")",
    "id": company.properties.domain ~ "," ~ (company.properties.discord_server | default("REWST-COMMUNITY", true))
  }
  for company in CTX.filtered_company_output
] }}
